using System.Collections;
using System.Linq;
using UnityEngine;
namespace CastleFight {
public sealed partial class PcGame {
    IEnumerator MechPowerChecks(string folder) {
        MechClear();var plant=ChaosHut(0,"h09T",new Vector2(-148,32));var factory=ChaosHut(0,"h05X",new Vector2(-143,32));var outside=ChaosHut(0,"h05X",new Vector2(-141.96f,32));var enemy=ChaosHut(1,"h000",new Vector2(-145,32));factory.paused=outside.paused=enemy.paused=true;
        Check(match.MechPowered(factory)&&!match.MechPowered(outside)&&!match.MechPowered(enemy),"Power plant respects native 180 radius and alliance");float baseArmor=HumanMatch.F(match.Lines[factory.kind].buildingStats,"armor");Check(match.BuildingArmor(factory)==baseArmor+2,"Powered buildings receive two armor");var second=ChaosHut(0,"h09T",plant.position);Check(match.BuildingArmor(factory)==baseArmor+2,"Overlapping power plants do not stack");
        factory.mana=0;factory.paused=false;factory.spawnLeft=10000;NorthTime(1);Check(factory.mana>=.249f,"Power plant adds a flat quarter mana per second to nearby buildings");
        factory.spawnLeft=.01f;Tick(.05f);factory.paused=true;var trained=match.Units.Last(u=>u.kind==factory.kind);trained.castPause=10000;float nativeHp=HumanMatch.F(match.Lines[trained.kind].stats,"hp");NorthTime(.55f);
        Check(trained.mechEmpowered&&trained.maxHp==nativeHp+100&&trained.armor==match.Lines[trained.kind].armor+2&&Mathf.Abs(trained.auraDamage-.2f)<.001f,"Powered production grants permanent 100 HP, two armor and twenty percent attack");match.EmpowerMech(trained);Check(trained.maxHp==nativeHp+100,"Repeated birth empowerment cannot stack");
        outside.paused=false;outside.spawnLeft=.01f;Tick(.05f);outside.paused=true;var ordinary=match.Units.Last(u=>u.kind==outside.kind);ordinary.castPause=10000;Check(!ordinary.mechEmpowered&&ordinary.maxHp==nativeHp,"Unpowered production retains the unmodified source fighter");
        match.Huts.Remove(plant);match.Huts.Remove(second);Check(match.BuildingArmor(factory)==baseArmor&&!match.MechPowered(factory)&&trained.maxHp==nativeHp+100,"Plant loss removes building power but preserves the newborn's permanent enhancement");
        MechClear();plant=ChaosHut(0,"h09T",HumanMatch.CastlePosition(0));Check(match.MechCastlePowered(0)&&!match.MechCastlePowered(1),"Castle power uses its own side and native radius");float hp=match.CastleHp[0];var attacker=MechUnit(1,"h000",HumanMatch.CastlePosition(0)+Vector2.right*3);attacker.castPause=0;attacker.cooldown=0;NorthTime(1);Check(match.CastleHp[0]<hp,"Powered castle still receives real ordinary weapon damage");
        MechClear();var maintenance=ChaosHut(0,"h100",new Vector2(-148,32));var machine=MechUnit(0,"h05X",new Vector2(-140,32));var organic=MechDummy(0,new Vector2(-139,32));machine.hp=100;NorthTime(.6f);
        Check(machine.auraArmor==3&&machine.auraRegen==5&&machine.auraIds.Contains("A10C"),"Maintenance facility grants native global mechanical armor and regeneration");Check(organic.auraArmor==0&&organic.auraRegen==0,"Maintenance excludes organic allies");hp=machine.hp;NorthTime(1);Check(machine.hp>=hp+4.9f,"Maintenance regeneration actually restores fighter HP");
        var duplicate=ChaosHut(0,"h100",maintenance.position);NorthTime(.55f);Check(machine.auraArmor==3&&machine.auraRegen==5,"Two maintenance facilities cannot double their native auras");match.Huts.Clear();NorthTime(.55f);Check(machine.auraArmor==0&&machine.auraRegen==0,"Maintenance aura disappears when its sources disappear");
        MechClear();var mechanic=MechUnit(0,"h069",new Vector2(-148,32));mechanic.castPause=0;var target=ChaosHut(0,"h05X",new Vector2(-140,32));target.hp=target.maxHp-300;target.paused=true;hp=target.hp;Tick(.05f);
        Check(target.hp>hp&&mechanic.pose=="Attack"&&match.MechRepairs>0,"Mechanic actually repairs an allied building in native range");Check(match.MechRepairGold[0]>0||match.Gold[0]<100000,"Mechanical repair accrues proportional native gold cost");Check(mechanic.summonLeft>119&&HumanMatch.F(match.Lines[mechanic.kind].stats,"hp")>0&&match.Invulnerable(mechanic),"Mechanic preserves invulnerability and its two-minute summoned lifetime");
        match.Gold[0]=0;match.Wood[0]=0;hp=target.hp;NorthTime(.5f);Check(target.hp==hp,"Repair cannot spend resources unavailable after reservations and fractional debt");
        match.Gold[0]=1000;match.Wood[0]=1000;mechanic.summonLeft=.01f;Tick(.05f);Check(mechanic.hp==0&&mechanic.deathProcessed,"Mechanic timed life expires despite native invulnerability");
        MechClear();mechanic=MechUnit(0,"h069",new Vector2(-120,32));mechanic.castPause=0;match.CastleHp[0]-=400;Vector2 before=mechanic.position;Tick(.05f);Check(mechanic.position!=before&&mechanic.mechRepairTarget==-1,"Mechanic walks to a damaged castle before repairing it");mechanic.position=HumanMatch.CastlePosition(0);hp=match.CastleHp[0];Tick(.05f);Check(match.CastleHp[0]>hp&&match.CastleHp[0]<=HumanMatch.CastleMax,"Mechanic restores virtual castle HP without exceeding maximum");
        MechClear();mechanic=MechUnit(0,"h069",Vector2.zero);mechanic.castPause=0;machine=MechUnit(0,"h05X",Vector2.right*3);machine.hp-=250;organic=MechDummy(0,Vector2.right);organic.hp-=500;hp=machine.hp;Tick(.05f);Check(machine.hp>hp&&mechanic.mechRepairTarget==machine.id,"Without damaged structures the mechanic chooses mechanical allies over organic units");
        RenderMatch();selectedUnit=mechanic.id;builderSelected=false;controls.FocusWorld(World(mechanic.position),35);yield return Shot(folder,"05-mech-power-repair");
    }
    IEnumerator MechPayloadChecks(string folder) {
        MechClear();var carrier=MechUnit(0,"h09J",new Vector2(-148,32));carrier.castPause=0;carrier.mana=100;
        Check(match.Cast(carrier,"A095")&&carrier.mana==50&&HumanMatch.F(match.Abilities["A095"],"cd")==0,"Mine-layer spends fifty mana with no invented spell cooldown");carrier.castPause=10000;var payload=match.Shots.Last();var job=match.MechJobs.Single(v=>v.kind=="mine");float distance=Vector2.Distance(job.point,carrier.position);
        Check(Mathf.Abs(payload.weapon.speed-700f/30)<.001f&&Mathf.Abs(payload.weapon.arc-.3f)<.001f&&!payload.homing,"Mine payload preserves native 700 speed, arc and fixed landing point");Check(distance>=70f/30&&distance<=10&&MechMissile(payload),"Mine throw uses native random 70 to 300 radius and classic model");
        match.DamageUnit(carrier,1000000,1,"chaos",false,true);for(int i=0;i<50&&!match.Units.Any(u=>match.MechMine(u));i++)Tick(.05f);var mine=match.Units.Single(u=>match.MechMine(u));Check(mine.hp>0&&match.MechMines>0,"A launched mine lands after its carrier dies");
        var victim=MechDummy(1,mine.position);var air=MechDummy(1,mine.position,"h015");int army=match.ArmyCount(0);NorthTime(2);Check(mine.hp>0&&mine.mechMineAge>1.95f&&match.Hidden(mine)&&army==0,"Mine becomes hidden after two seconds and occupies no fighter slot");NorthTime(2.8f);Check(mine.hp>0&&victim.hp==10000,"Mine waits its full five-second arming period");for(int i=0;i<10&&mine.hp>0;i++)Tick(.05f);Check(mine.hp==0&&victim.hp==10000,"Armed mine triggers and delays its explosion");NorthTime(.35f);
        Check(Mathf.Abs(victim.hp-9750)<.1f&&air.hp==10000,"Mine explosion deals native 250 magic damage after the delay and excludes air");Check(!match.MechJobs.Any(v=>v.kind=="blast"),"Mine death blast is consumed once");
        MechClear();var grenadier=MechUnit(0,"h09P",new Vector2(-148,32));grenadier.castPause=0;victim=MechDummy(1,new Vector2(-140,32));victim.maxMana=500;victim.mana=200;victim.manaRegen=0;air=MechDummy(1,victim.position,"h015");var ally=MechDummy(0,victim.position);
        Check(match.Cast(grenadier,"A09D",victim.id)&&victim.hp==10000&&HumanMatch.F(match.Abilities["A09D"],"cd")==15,"Grenade releases without immediate damage and retains native fifteen-second cooldown");grenadier.castPause=10000;payload=match.Shots.Last();Check(Mathf.Abs(payload.weapon.speed-700f/30)<.001f&&Mathf.Abs(payload.weapon.arc-.2f)<.001f&&MechMissile(payload),"Grenade uses its native classic missile, speed and arc");
        match.DamageUnit(grenadier,1000000,1,"chaos",false,true);NorthTime(1);Check(victim.hp<9900&&victim.mana==100&&victim.effects.Any(e=>e.id=="A09E"),"Grenade survives its source, applies shock and separately burns up to one hundred mana");Check(air.hp==10000&&ally.hp==10000&&match.Stat(victim,"damage")==0,"Grenade excludes air and allies and does not turn spell damage into an attack bonus");
        MechClear();grenadier=MechUnit(0,"h09P",Vector2.zero);grenadier.castPause=0;victim=MechDummy(1,Vector2.right*4);victim.maxMana=500;victim.mana=200;victim.manaRegen=0;victim.spellResist=1;match.Cast(grenadier,"A09D",victim.id);Check(match.MechJobs.Count==0,"Magic immunity prevents selecting a grenade's primary target");
        var primary=MechDummy(1,Vector2.right*5);match.Cast(grenadier,"A09D",primary.id);grenadier.castPause=10000;NorthTime(1);Check(victim.mana==100&&victim.hp<10000&&!victim.effects.Any(e=>e.id=="A09E"),"An immune unit in grenade splash resists shock but retains native physical mana burn");
        MechClear();var sapper=MechUnit(0,"h05M",new Vector2(-148,32));victim=MechDummy(1,sapper.position);match.DamageUnit(sapper,1000000,1,"chaos",false,true);Check(victim.hp==10000,"Ordinary sapper death queues its delayed blast");NorthTime(.35f);Check(Mathf.Abs(victim.hp-9850)<.1f,"Ordinary sapper death uses native 150 magic damage");
        MechClear();sapper=MechUnit(0,"h05M",new Vector2(-148,32));sapper.castPause=0;victim=MechDummy(1,sapper.position);Tick(.05f);Check(sapper.mechFuse&&victim.hp==10000,"Sapper arms near an eligible enemy before dealing damage");NorthTime(.15f);Check(sapper.hp==0&&Mathf.Abs(victim.hp-9725)<.1f,"Active sapper uses native 275 damage and suicide");NorthTime(.4f);Check(Mathf.Abs(victim.hp-9725)<.1f,"Active suicide does not trigger a second passive blast");
        RenderMatch();controls.FocusWorld(World(victim.position),32);yield return Shot(folder,"06-mech-payloads");
    }
